tasks.starter:
// signal speed in fibre ~200,000 km/s
const SPEED_KM_S = 200000;

// links: array of { km, bps }; packet size in bits
function oneWayMs(links, packetBits) {
  let propMs = 0;
  for (const link of links) {
    propMs += (link.km / SPEED_KM_S) * 1000;
  }
  // store-and-forward: each hop must receive the whole packet before forwarding
  const firstHop = links[0];
  const transMs = (packetBits / firstHop.bps) * 1000;   // charged once
  return Math.round(propMs + transMs);
}

const links = [
  { km: 1000, bps: 10e6 },
  { km: 1000, bps: 10e6 },
  { km: 1000, bps: 10e6 }
];
console.log(oneWayMs(links, 100000) + ' ms');

